import zipfile, re
from xml.etree import ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

z = zipfile.ZipFile('sales_data.xlsx')
print("FILES IN ARCHIVE:")
for n in z.namelist():
    print("  ", n)

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))

relmap = {r.get('Id'): r.get('Target') for r in rels}

# shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sst.findall('m:si', NS):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared.append(text)

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

for sheet in wb.findall('m:sheet', NS):
    name = sheet.get('name')
    rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    target = relmap.get(rid, '')
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    print(f"\n=== SHEET: {name} (file: {target}) ===")
    root = ET.fromstring(z.read(target))
    sd = root.find('m:sheetData', NS)
    if sd is None:
        print("  (empty)")
        continue
    for row in sd.findall('m:row', NS):
        r = row.get('r')
        cells = []
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            isv = c.find('m:is', NS)
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr' and isv is not None:
                val = ''.join(tt.text or '' for tt in isv.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            elif v is not None:
                val = v.text
            else:
                val = ''
            cells.append(f"{ref}={val!r}")
        print(f"  row {r}: " + " | ".join(cells))

import openpyxl
wb = openpyxl.load_workbook('sales_data.xlsx')
for ws in wb.worksheets:
    print(f"Sheet: {ws.title} dims={ws.dimensions} max_row={ws.max_row} max_col={ws.max_column}")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 30)):
        parts = []
        for c in row:
