                parts.append(f"{c.coordinate}={c.value!r}")
        if parts:
            print("  " + " | ".join(parts))
    print("Number formats (header row):")
    for c in ws[1]:
        if c.value is not None:
            print(f"  {c.coordinate} fmt={c.number_format!r}")

import os, re, zipfile
import xml.etree.ElementTree as ET

SRC = 'sales_data.xlsx'
cell_re = re.compile(r'<c\b[^>]*?(?:/>|>.*?</c>)', re.S)

zin = zipfile.ZipFile(SRC)
entries = {i.filename: zin.read(i.filename) for i in zin.infolist()}
zin.close()

sheet_path = 'xl/worksheets/sheet1.xml'
sheet_text = entries[sheet_path].decode('utf-8')


def cell_refs(row_xml):
    out = {}
    for cm in cell_re.finditer(row_xml):
        ref_m = re.search(r'\br="([A-Z]+)(\d+)"', cm.group(0))
        if not ref_m:
            continue
        vm = re.search(r'<v>(.*?)</v>', cm.group(0), re.S)
        out[ref_m.group(1) + ref_m.group(2)] = vm.group(1) if vm else None
    return out


def val_of(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


updated = 0
rows_text = {}
for rn in range(2, 11):
    row_m = re.search(r'(<row\b[^>]*\br="%d"[^>]*>)(.*?)(</row>)' % rn, sheet_text, re.S)
    if not row_m:
        continue
    open_tag, body, close_tag = row_m.group(1), row_m.group(2), row_m.group(3)
    refs = cell_refs(body)
    new_body = body
    for cm in cell_re.finditer(body):
        ref_m = re.search(r'\br="([A-Z]+)(\d+)"', cm.group(0))
        if not ref_m or ref_m.group(1) != 'H':
            continue
        cell_xml = cm.group(0)
        fm = re.search(r'<f>(.*?)</f>', cell_xml, re.S)
        if not fm:
            continue
        operands = re.findall(r'([A-Z]+\d+)', fm.group(1))
        if len(operands) < 2:
            continue
        num = val_of(refs.get(operands[0]))
        den = val_of(refs.get(operands[1]))
        value = (num / den) if (num is not None and den) else 0.0
        new_cell = re.sub(r'(<v>)(.*?)(</v>)', r'\g<1>%r\g<3>' % value, cell_xml, count=1)
        new_body = new_body.replace(cell_xml, new_cell, 1)
        updated += 1
        print('H%d = %s / %s -> %r' % (rn, operands[0], operands[1], value))
    if new_body != body:
        sheet_text = sheet_text[:row_m.start(2)] + new_body + sheet_text[row_m.end(2):]

entries[sheet_path] = sheet_text.encode('utf-8')

tmp = SRC + '.tmp'
with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as zout:
    for name, data in entries.items():
        zout.writestr(name, data)
os.replace(tmp, SRC)
print('cached values updated:', updated)

# Validate every XML part is well-formed and no Excel error tokens remain
bad = []
for name, data in entries.items():
    if name.endswith('.xml') or name.endswith('.rels'):
        try:
            ET.fromstring(data)
        except ET.ParseError as e:
            bad.append((name, str(e)))
print('xml validation errors:', bad if bad else 'none')

for name, data in entries.items():
    text = data.decode('utf-8', errors='ignore')
    for tok in ['#REF!', '#DIV/0!', '#VALUE!', '#NAME?', '#N/A']:
        if tok in text:
            print('FOUND ERROR TOKEN', tok, 'in', name)
print('error token scan: done')

import html, os, re, sys, zipfile
import xml.etree.ElementTree as ET

SRC = 'sales_data.xlsx'


def col_letter(idx):
    s = ''
    while idx:
        idx, rem = divmod(idx - 1, 26)
        s = chr(65 + rem) + s
    return s


def col_index(letters):
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch.upper()) - 64)
    return n


cell_re = re.compile(r'<c\b[^>]*?(?:/>|>.*?</c>)', re.S)
attr_re = re.compile(r'(\w+)="([^"]*)"')

zin = zipfile.ZipFile(SRC)
entries = {i.filename: zin.read(i.filename) for i in zin.infolist()}
zin.close()

# Locate first worksheet part via workbook.xml + rels
wb_text = entries['xl/workbook.xml'].decode('utf-8')
rels_text = entries['xl/_rels/workbook.xml.rels'].decode('utf-8')
rid = re.search(r'<sheet\b[^>]*\br:id="([^"]+)"', wb_text).group(1)
target = None
for rel in re.finditer(r'<Relationship\b[^>]*/>', rels_text):
    if 'Id="%s"' % rid in rel.group(0):
        target = re.search(r'Target="([^"]+)"', rel.group(0)).group(1)
        break
sheet_path = ('xl/' + target.lstrip('/')) if not target.startswith('/') else target[1:]
print('worksheet part:', sheet_path)

# Shared strings
shared = []
if 'xl/sharedStrings.xml' in entries:
    sst = entries['xl/sharedStrings.xml'].decode('utf-8')
    for si in re.finditer(r'<si\b.*?</si>', sst, re.S):
        shared.append(html.unescape(''.join(re.findall(r'<t[^>]*>(.*?)</t>', si.group(0), re.S))))

sheet_text = entries[sheet_path].decode('utf-8')


def cell_value(cell_xml):
    m = re.search(r'\bt="([^"]+)"', cell_xml)
    t = m.group(1) if m else None
    vm = re.search(r'<v>(.*?)</v>', cell_xml, re.S)
    if t == 's' and vm:
        return shared[int(vm.group(1).strip())]
    if t == 'inlineStr':
        return html.unescape(''.join(re.findall(r'<t[^>]*>(.*?)</t>', cell_xml, re.S)))
    if vm:
        return vm.group(1)
    return None


# Find header row containing Profit and Revenue/Sales columns
header_row = profit_col = rev_col = cost_col = None
for rn in range(1, 21):
    row_m = re.search(r'<row\b[^>]*\br="%d"[^>]*>(.*?)</row>' % rn, sheet_text, re.S)
    if not row_m:
        continue
    cells = {}
    for cm in cell_re.finditer(row_m.group(1)):
        ref_m = re.search(r'\br="([A-Z]+)\d+"', cm.group(0))
        if not ref_m:
            continue
        ci = col_index(ref_m.group(1))
        v = cell_value(cm.group(0))
        cells[ci] = str(v).lower() if v is not None else ''
    p = [ci for ci, s in cells.items() if 'profit' in s]
    rv = [ci for ci, s in cells.items() if 'revenue' in s]
    if not rv:
        rv = [ci for ci, s in cells.items() if 'sales' in s]
    co = [ci for ci, s in cells.items() if 'cost' in s or 'cogs' in s]
    if p and rv:
        header_row, profit_col, rev_col = rn, p[0], rv[0]
        if co:
            cost_col = co[0]
        break

print('header_row:', header_row, 'profit_col:', profit_col, 'rev_col:', rev_col, 'cost_col:', cost_col)
if header_row is None:
    sys.exit('Could not locate Profit and Revenue/Sales columns in any header row')

# Global extents
refs = []
for cm in cell_re.finditer(sheet_text):
    ref_m = re.search(r'\br="([A-Z]+)(\d+)"', cm.group(0))
    if ref_m:
        refs.append((col_index(ref_m.group(1)), int(ref_m.group(2))))
max_row = max(r for c, r in refs)
new_col = max(c for c, r in refs) + 1
new_letter = col_letter(new_col)
print('new column:', new_letter, '(max_row =', str(max_row) + ')')

# --- styles.xml: percent number format ---
styles_text = None
percent_style = None
if 'xl/styles.xml' in entries:
    styles_text = entries['xl/styles.xml'].decode('utf-8')
    cellXfs_m = re.search(r'<cellXfs\b[^>]*>(.*?)</cellXfs>', styles_text, re.S)
    if cellXfs_m:
        xfs = re.compile(r'<xf\b[^>]*?(?:/>|>.*?</xf>)', re.S).findall(cellXfs_m.group(1))
        usage = {}
        for rn in range(header_row + 1, max_row + 1):
            row_m = re.search(r'<row\b[^>]*\br="%d"[^>]*>(.*?)</row>' % rn, sheet_text, re.S)
            if not row_m:
                continue
            for cm in cell_re.finditer(row_m.group(1)):
                ref_m = re.search(r'\br="([A-Z]+)\d+"', cm.group(0))
                if not ref_m or col_index(ref_m.group(1)) != rev_col:
                    continue
                sm = re.search(r'\bs="(\d+)"', cm.group(0))
                if sm:
                    usage[sm.group(1)] = usage.get(sm.group(1), 0) + 1
        base_idx = max(usage, key=usage.get) if usage else None
        base_xf = xfs[int(base_idx)] if base_idx and int(base_idx) < len(xfs) else None
        mfmt = re.search(r'<numFmt\b[^>]*formatCode="0\.0%"', styles_text)
        if mfmt:
            percent_id = int(re.search(r'numFmtId="(\d+)"', mfmt.group(0)).group(1))
        else:
            custom = [int(x) for x in re.findall(r'numFmtId="(\d+)"', styles_text) if int(x) >= 164]
            percent_id = (max(custom) + 1) if custom else 164
            nf_xml = '<numFmt numFmtId="%d" formatCode="0.0%%"/>' % percent_id
            nm = re.search(r'(<numFmts\b[^>]*>)(.*?)(</numFmts>)', styles_text, re.S)
            if nm:
                tag = nm.group(1)
                cnt = re.search(r'count="(\d+)"', tag)
                tag = re.sub(r'count="\d+"', 'count="%d"' % (int(cnt.group(1)) + 1), tag, count=1) if cnt else tag
                styles_text = styles_text[:nm.start(1)] + tag + nm.group(2) + nf_xml + nm.group(3) + styles_text[nm.end(3):]
            else:
                m3 = re.search(r'<styleSheet\b[^>]*>', styles_text)
                styles_text = styles_text[:m3.end()] + '<numFmts count="1">' + nf_xml + '</numFmts>' + styles_text[m3.end():]
        if base_xf:
            om = re.search(r'<xf\b([^>]*?)(?:/>|>)', base_xf)
            attrs = dict(attr_re.findall(om.group(1)))
        else:
            attrs = {'fontId': '0', 'fillId': '0', 'borderId': '0', 'xfId': '0'}
        attrs['numFmtId'] = str(percent_id)
        attrs['applyNumberFormat'] = '1'
        new_xf = '<xf ' + ' '.join('%s="%s"' % kv for kv in attrs.items()) + '/>'
        cm2 = re.search(r'(<cellXfs\b[^>]*>)(.*?)(</cellXfs>)', styles_text, re.S)
        ctag = cm2.group(1)
        ccnt = re.search(r'count="(\d+)"', ctag)
        ctag = re.sub(r'count="\d+"', 'count="%d"' % (int(ccnt.group(1)) + 1), ctag, count=1) if ccnt else ctag
        styles_text = styles_text[:cm2.start(1)] + ctag + cm2.group(2) + new_xf + cm2.group(3) + styles_text[cm2.end(3):]
        percent_style = str(len(xfs))
print('percent_style_index:', percent_style)


def insert_cell_in_row(rn, cell_xml, col):
    global sheet_text
    row_m = re.search(r'(<row\b[^>]*\br="%d"[^>]*>)(.*?)(</row>)' % rn, sheet_text, re.S)
    if not row_m:
        return False
    open_tag, body, close_tag = row_m.group(1), row_m.group(2), row_m.group(3)
    pos = 0
    for cm in cell_re.finditer(body):
        ref_m = re.search(r'\br="([A-Z]+)\d+"', cm.group(0))
        if ref_m and col_index(ref_m.group(1)) < col:
            pos = cm.end()
        else:
            break
    new_body = body[:pos] + cell_xml + body[pos:]
    if 'spans=' in open_tag:
        cols = [col_index(mm.group(1)) for mm in re.finditer(r'\br="([A-Z]+)\d+"', new_body)]
        if cols:
            open_tag = re.sub(r'spans="[^"]*"', 'spans="%d:%d"' % (min(cols), max(cols)), open_tag, count=1)
    sheet_text = sheet_text[:row_m.start()] + open_tag + new_body + close_tag + sheet_text[row_m.end():]
    return True


# Header cell
header_style = None
hrow_m = re.search(r'<row\b[^>]*\br="%d"[^>]*>(.*?)</row>' % header_row, sheet_text, re.S)
for cm in cell_re.finditer(hrow_m.group(1)):
    ref_m = re.search(r'\br="([A-Z]+)\d+"', cm.group(0))
    if ref_m and col_index(ref_m.group(1)) == rev_col:
        sm = re.search(r'\bs="(\d+)"', cm.group(0))
        if sm:
            header_style = sm.group(1)
        break
header_cell = '<c r="%s%d" t="inlineStr"%s><is><t>Profit Margin (%%)</t></is></c>' % (
    new_letter, header_row, (' s="%s"' % header_style) if header_style else '')
insert_cell_in_row(header_row, header_cell, new_col)

# Formula cells
added = 0
for rn in range(header_row + 1, max_row + 1):
    row_m = re.search(r'<row\b[^>]*\br="%d"[^>]*>(.*?)</row>' % rn, sheet_text, re.S)
    if not row_m or not cell_re.search(row_m.group(1)):
        continue
    den = '%s%d' % (col_letter(rev_col), rn)
    if profit_col:
        num = '%s%d' % (col_letter(profit_col), rn)
    elif cost_col:
        num = '(%s%d-%s%d)' % (col_letter(rev_col), rn, col_letter(cost_col), rn)
    else:
        continue
    formula = 'IFERROR(%s/%s,0)' % (num, den)
    sattr = ' s="%s"' % percent_style if percent_style is not None else ''
    cell_xml = '<c r="%s%d"%s><f>%s</f><v>0</v></c>' % (new_letter, rn, sattr, formula)
    if insert_cell_in_row(rn, cell_xml, new_col):
        added += 1
