        added += 1
print('formula cells added:', added)


def float_of(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


updated = 0
for rn in range(header_row + 1, max_row + 1):
    row_m = re.search(r'(<row\b[^>]*\br="%d"[^>]*>)(.*?)(</row>)' % rn, sheet_text, re.S)
    if not row_m:
        continue
    body = row_m.group(2)
    vals = {}
    for cm in cell_re.finditer(body):
        ref_m = re.search(r'\br="([A-Z]+)(\d+)"', cm.group(0))
        if ref_m:
            vm = re.search(r'<v>(.*?)</v>', cm.group(0), re.S)
            vals[ref_m.group(1) + ref_m.group(2)] = vm.group(1) if vm else None
    for cm in cell_re.finditer(body):
        ref_m = re.search(r'\br="([A-Z]+)(\d+)"', cm.group(0))
        if not ref_m or ref_m.group(1) != new_letter:
            continue
        fm = re.search(r'<f>(.*?)</f>', cm.group(0), re.S)
        if not fm:
            continue
        operands = re.findall(r'([A-Z]+\d+)', fm.group(1))
        if len(operands) < 2:
            continue
        num = float_of(vals.get(operands[0]))
        den = float_of(vals.get(operands[1]))
        value = (num / den) if (num is not None and den) else 0.0
        cell_xml = cm.group(0)
        new_cell = re.sub(r'(<v>)(.*?)(</v>)', r'\g<1>%r\g<3>' % value, cell_xml, count=1)
        body = body.replace(cell_xml, new_cell, 1)
        updated += 1
    sheet_text = sheet_text[:row_m.start(2)] + body + sheet_text[row_m.end(2):]
print('cached values updated:', updated)

refs = []
for cm in cell_re.finditer(sheet_text):
